-- Flyway V1: PostgreSQL schema for User & Identity Service
-- Apply to an existing, empty target database selected by the datasource.
-- Source: UserServiceDB.sql; original schema, constraints and indexes preserved.

-- =========================================================
-- 1. USERS
-- =========================================================

CREATE TABLE "Users" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    "UserName" VARCHAR(50) NOT NULL,
    "PasswordHash" VARCHAR(255) NULL,
    "Email" VARCHAR(255) NOT NULL,
    "FullName" VARCHAR(150) NOT NULL,
    "PhoneNumber" VARCHAR(20) NULL,

    "Status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',

    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "UQ_Users_UserName"
        UNIQUE ("UserName"),

    CONSTRAINT "UQ_Users_Email"
        UNIQUE ("Email"),

    CONSTRAINT "CK_Users_Status"
        CHECK ("Status" IN (
            'ACTIVE',
            'BANNED'
        ))
);


-- =========================================================
-- 2. ROLES
-- =========================================================

CREATE TABLE "Roles" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    "Name" VARCHAR(30) NOT NULL,

    CONSTRAINT "UQ_Roles_Name"
        UNIQUE ("Name")
);


-- =========================================================
-- 3. USER ROLES
-- Quan hệ N-N giữa Users và Roles
-- =========================================================

CREATE TABLE "UserRoles" (
    "UserId" INTEGER NOT NULL,
    "RoleId" INTEGER NOT NULL,

    CONSTRAINT "PK_UserRoles"
        PRIMARY KEY ("UserId", "RoleId"),

    CONSTRAINT "FK_UserRoles_Users"
        FOREIGN KEY ("UserId")
        REFERENCES "Users" ("Id")
        ON DELETE CASCADE,

    CONSTRAINT "FK_UserRoles_Roles"
        FOREIGN KEY ("RoleId")
        REFERENCES "Roles" ("Id")
        ON DELETE CASCADE
);


-- =========================================================
-- 4. USER IDENTITIES
-- Lưu phương thức đăng nhập bên ngoài
-- Ví dụ: Google
-- =========================================================

CREATE TABLE "UserIdentities" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    "UserId" INTEGER NOT NULL,

    "Provider" VARCHAR(30) NOT NULL,
    "ProviderUserId" VARCHAR(255) NOT NULL,

    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "FK_UserIdentities_Users"
        FOREIGN KEY ("UserId")
        REFERENCES "Users" ("Id")
        ON DELETE CASCADE,

    -- Một tài khoản Google chỉ được liên kết với một User
    CONSTRAINT "UQ_UserIdentities_Provider_ProviderUserId"
        UNIQUE ("Provider", "ProviderUserId"),

    -- Hiện tại mỗi User chỉ liên kết tối đa một tài khoản
    -- cho mỗi Provider, ví dụ chỉ một Google Account
    CONSTRAINT "UQ_UserIdentities_UserId_Provider"
        UNIQUE ("UserId", "Provider")
);


-- =========================================================
-- 5. REFRESH TOKENS
-- Quản lý Refresh Token và Refresh Token Rotation
-- =========================================================

CREATE TABLE "RefreshTokens" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    "UserId" INTEGER NOT NULL,

    "TokenHash" VARCHAR(255) NOT NULL,

    "ExpiresAt" TIMESTAMPTZ NOT NULL,
    "RevokedAt" TIMESTAMPTZ NULL,

    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    "ReplacedByTokenId" INTEGER NULL,

    CONSTRAINT "UQ_RefreshTokens_TokenHash"
        UNIQUE ("TokenHash"),

    CONSTRAINT "FK_RefreshTokens_Users"
        FOREIGN KEY ("UserId")
        REFERENCES "Users" ("Id")
        ON DELETE CASCADE,

    -- Self-reference:
    -- token cũ chỉ tới token mới thay thế nó
    CONSTRAINT "FK_RefreshTokens_ReplacedByToken"
        FOREIGN KEY ("ReplacedByTokenId")
        REFERENCES "RefreshTokens" ("Id")
        ON DELETE SET NULL,

    CONSTRAINT "CK_RefreshTokens_ExpiresAt"
        CHECK ("ExpiresAt" > "CreatedAt"),

    CONSTRAINT "CK_RefreshTokens_NotReplaceItself"
        CHECK (
            "ReplacedByTokenId" IS NULL
            OR "ReplacedByTokenId" <> "Id"
        )
);


-- =========================================================
-- 6. VERIFICATION CODES
--
-- REGISTER:
--   xác minh email khi đăng ký Local Account
--
-- PASSWORD_RESET:
--   quên / đặt lại mật khẩu
--
-- SET_PASSWORD:
--   tạo mật khẩu lần đầu cho Google-only Account
--
-- Không FK tới Users vì REGISTER xảy ra trước khi
-- User được tạo.
-- =========================================================

CREATE TABLE "VerificationCodes" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    "Email" VARCHAR(255) NOT NULL,

    "Purpose" VARCHAR(30) NOT NULL,

    "CodeHash" VARCHAR(255) NOT NULL,

    "ExpiresAt" TIMESTAMPTZ NOT NULL,

    "UsedAt" TIMESTAMPTZ NULL,

    "AttemptCount" INTEGER NOT NULL DEFAULT 0,

    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "CK_VerificationCodes_Purpose"
        CHECK ("Purpose" IN (
            'REGISTER',
            'PASSWORD_RESET',
            'SET_PASSWORD'
        )),

    CONSTRAINT "CK_VerificationCodes_AttemptCount"
        CHECK ("AttemptCount" >= 0),

    CONSTRAINT "CK_VerificationCodes_ExpiresAt"
        CHECK ("ExpiresAt" > "CreatedAt")
);


-- =========================================================
-- INDEXES
-- =========================================================

-- Tìm các Refresh Token của một User
CREATE INDEX "IDX_RefreshTokens_UserId"
ON "RefreshTokens" ("UserId");


-- Hỗ trợ tìm / dọn token hết hạn
CREATE INDEX "IDX_RefreshTokens_ExpiresAt"
ON "RefreshTokens" ("ExpiresAt");


-- Tìm mã xác minh theo Email + Purpose
CREATE INDEX "IDX_VerificationCodes_Email_Purpose"
ON "VerificationCodes" ("Email", "Purpose");


-- Hỗ trợ dọn Verification Code hết hạn
CREATE INDEX "IDX_VerificationCodes_ExpiresAt"
ON "VerificationCodes" ("ExpiresAt");
